// Staleness gate: claims carry dates or they don't ship (plain JS)
function stalenessGate(claim, todayISO, maxAgeDays) {
  if (!claim.asOf) return { ok: false, error: "missing-as-of" };
  const ageDays = (Date.parse(todayISO) - Date.parse(claim.asOf)) / 86400000;
  if (!(ageDays >= 0)) return { ok: false, error: "future-date" };
  if (ageDays > maxAgeDays) return { ok: false, error: "stale:" + Math.floor(ageDays) + "d" };
  return { ok: true };
}
